# v3.90: Função helper para mostrar estado do sistema
def print_system_state(label=""):
    """Mostra estado atual do sistema (RAM, CPU, etc.)"""
    if PSUTIL_AVAILABLE:
        process = psutil.Process(os.getpid())
        mem_info = process.memory_info()
        cpu_percent = process.cpu_percent(interval=0.1)
        
        print(f"💻 SYSTEM STATE {label}:")
        print(f"   RAM: {mem_info.rss / 1024 / 1024:.1f} MB")
        print(f"   CPU: {cpu_percent:.1f}%")
        print(f"   Threads: {threading.active_count()}")
    else:
        print(f"💻 SYSTEM STATE {label}: (psutil not available)")

