@dataclass
class CreativeIdea:
    """
    Ideia criativa gerada.
    
    Criatividade = Novidade + Utilidade
    """
    idea_id: str
    content: str
    novelty_score: float      # Quão nova (0-1)
    usefulness_score: float   # Quão útil (0-1)
