# MÓDULO 42: INTROSPECTION ENGINE (POST 42)
# ═══════════════════════════════════════════════════════════════════════════

@dataclass
class CognitiveState:
    """Estado cognitivo interno"""
    state_id: str
    timestamp: float
    active_modules: List[str]
    processing_load: float  # 0-1
    confidence_level: float  # 0-1
    current_focus: str
    
@dataclass
class IntrospectiveInsight:
    """Insight de introspecção"""
    insight_id: str
    insight_type: str  # "pattern", "bias", "limitation", "strength"
    description: str
    severity: float  # 0-1
    recommendations: List[str]
    
@dataclass
class ProcessTrace:
    """Rastreamento de processo cognitivo"""
    trace_id: str
    process_name: str
    steps: List[str]
    duration: float
    success: bool
    bottlenecks: List[str]

class RealIntrospectionEngine:
    """
    POST42: Introspection Engine — REAL Deep Self-Examination
    
    Introspecção = auto-exame profundo dos processos cognitivos internos.
    "Know thyself" - Ancient philosophy applied to AI cognition
    
    Princípios Centrais:
    - Self-examination: Examinar estados cognitivos internos
    - Process reflection: Refletir sobre processos de pensamento
    - Bias detection: Detectar vieses e limitações
    - Performance analysis: Analisar desempenho cognitivo
    - Self-improvement: Identificar áreas de melhoria
    
    Componentes:
    1. State Monitor: Monitora estados cognitivos internos
    2. Process Tracer: Rastreia processos de pensamento
    3. Pattern Detector: Detecta padrões em operações
    4. Bias Detector: Identifica vieses cognitivos
    5. Insight Generator: Gera insights introspectivos
    
    Multiplica:
    • × POST24 (Metacognition): Metacognition + Introspection = auto-conhecimento completo
    • × POST17 (Consciousness): Consciousness examina via introspection
    • × POST15 (RSI): RSI usa introspection para melhorar
    • × POST8 (Executive): Executive usa insights para controle
    
    Baseado em:
    - Introspection in Psychology (Wundt, 1879)
    - Computational Self-Models (Graziano, 2013)
    - Meta-Reasoning (Cox, 2005)
    - Reflective Agents (Maes, 1987)
    """
    
    def __init__(self, metacognition=None, consciousness=None, rsi=None):
        self.metacognition = metacognition
        self.consciousness = consciousness
        self.rsi = rsi
        
        # State tracking
        self.cognitive_states: List[CognitiveState] = []
        self.current_state: Optional[CognitiveState] = None
        
        # Process tracing
        self.process_traces: List[ProcessTrace] = []
        
        # Insights
        self.insights: List[IntrospectiveInsight] = []
        
        # Estatísticas
        self.total_states_examined = 0
        self.total_insights_generated = 0
        self.total_biases_detected = 0
        self.avg_confidence = 0.0
        
        print("🔍💭 POST 42 - RealIntrospectionEngine initialized (Deep introspection active)")
    
    def examine_cognitive_state(self, active_modules: List[str], 
                                processing_load: float,
                                current_focus: str) -> CognitiveState:
        """
        Examinar estado cognitivo atual.
        
        Args:
            active_modules: Módulos ativos
            processing_load: Carga de processamento (0-1)
            current_focus: Foco atual
        
        Returns:
            CognitiveState examinado
        """
        # Calcular confiança baseado em carga
        confidence = self._calculate_confidence(processing_load, len(active_modules))
        
        state = CognitiveState(
            state_id=str(uuid.uuid4()),
            timestamp=time.time(),
            active_modules=active_modules,
            processing_load=processing_load,
            confidence_level=confidence,
            current_focus=current_focus
        )
        
        self.cognitive_states.append(state)
        self.current_state = state
        self.total_states_examined += 1
        
        # Update statistics
        self._update_confidence_statistics(confidence)
        
        return state
    
    def _calculate_confidence(self, processing_load: float, num_modules: int) -> float:
        """Calcular nível de confiança"""
        # Alta carga = menor confiança
        load_factor = 1.0 - (processing_load * 0.5)
        
        # Mais módulos = maior confiança (até um limite)
        module_factor = min(1.0, num_modules / 10.0)
        
        confidence = (load_factor + module_factor) / 2.0
        
        return confidence
    
    def _update_confidence_statistics(self, confidence: float):
        """Atualizar estatísticas de confiança"""
        if self.avg_confidence == 0:
            self.avg_confidence = confidence
        else:
            self.avg_confidence = (self.avg_confidence + confidence) / 2
    
    def trace_cognitive_process(self, process_name: str, 
                               steps: List[str],
                               duration: float,
                               success: bool) -> ProcessTrace:
        """
        Rastrear processo cognitivo.
        
        Args:
            process_name: Nome do processo
            steps: Passos executados
            duration: Duração
            success: Sucesso ou falha
        
        Returns:
            ProcessTrace
        """
        # Detectar bottlenecks (passos muito lentos)
        bottlenecks = self._detect_bottlenecks(steps, duration)
        
        trace = ProcessTrace(
            trace_id=str(uuid.uuid4()),
            process_name=process_name,
            steps=steps,
            duration=duration,
            success=success,
            bottlenecks=bottlenecks
        )
        
        self.process_traces.append(trace)
        
        # Gerar insights se encontrou problemas
        if bottlenecks or not success:
            self._generate_process_insights(trace)
        
        return trace
    
    def _detect_bottlenecks(self, steps: List[str], duration: float) -> List[str]:
        """Detectar bottlenecks em processo"""
        bottlenecks = []
        
        # Heurística: se duração > 1s, há bottleneck
        if duration > 1.0:
            bottlenecks.append("Long execution time")
        
        # Se muitos passos, pode ser ineficiente
        if len(steps) > 10:
            bottlenecks.append("Too many steps")
        
        return bottlenecks
    
    def _generate_process_insights(self, trace: ProcessTrace):
        """Gerar insights de processo"""
        if trace.bottlenecks:
            insight = IntrospectiveInsight(
                insight_id=str(uuid.uuid4()),
                insight_type="limitation",
                description=f"Process '{trace.process_name}' has bottlenecks: {', '.join(trace.bottlenecks)}",
                severity=0.6,
                recommendations=[
                    "Optimize critical path",
                    "Reduce number of steps",
                    "Parallelize when possible"
                ]
            )
            self.insights.append(insight)
            self.total_insights_generated += 1
    
    def detect_cognitive_patterns(self) -> List[str]:
        """
        Detectar padrões em processos cognitivos.
        
        Returns:
            Lista de padrões detectados
        """
        patterns = []
        
        # Analisar estados recentes
        recent_states = self.cognitive_states[-10:] if len(self.cognitive_states) >= 10 else self.cognitive_states
        
        if len(recent_states) >= 3:
            # Padrão 1: Sobrecarga constante
            avg_load = sum(s.processing_load for s in recent_states) / len(recent_states)
            if avg_load > 0.8:
                patterns.append("High processing load pattern")
            
            # Padrão 2: Baixa confiança
            avg_conf = sum(s.confidence_level for s in recent_states) / len(recent_states)
            if avg_conf < 0.5:
                patterns.append("Low confidence pattern")
            
            # Padrão 3: Foco disperso
            focuses = [s.current_focus for s in recent_states]
            if len(set(focuses)) == len(focuses):  # Todos diferentes
                patterns.append("Scattered focus pattern")
        
        return patterns
    
    def detect_biases(self) -> List[IntrospectiveInsight]:
        """
        Detectar vieses cognitivos.
        
        Returns:
            Lista de insights sobre vieses
        """
        bias_insights = []
        
        # Viés 1: Sempre usar mesmos módulos (confirmation bias analógico)
        if len(self.cognitive_states) >= 5:
            recent_modules = [s.active_modules for s in self.cognitive_states[-5:]]
            all_modules = set()
            for modules in recent_modules:
                all_modules.update(modules)
            
            if len(all_modules) < 3:  # Muito poucos módulos
                insight = IntrospectiveInsight(
                    insight_id=str(uuid.uuid4()),
                    insight_type="bias",
                    description="Module usage bias: Using only few modules consistently",
                    severity=0.5,
                    recommendations=["Diversify module usage", "Explore alternative approaches"]
                )
                bias_insights.append(insight)
                self.total_biases_detected += 1
        
        # Viés 2: Processos sempre falhando
        if len(self.process_traces) >= 5:
            recent_traces = self.process_traces[-5:]
            failure_rate = sum(1 for t in recent_traces if not t.success) / len(recent_traces)
            
            if failure_rate > 0.6:
                insight = IntrospectiveInsight(
                    insight_id=str(uuid.uuid4()),
                    insight_type="limitation",
                    description="High failure rate in recent processes",
                    severity=0.7,
                    recommendations=["Review process logic", "Increase validation", "Adjust parameters"]
                )
                bias_insights.append(insight)
        
        # Adicionar ao registro
        self.insights.extend(bias_insights)
        self.total_insights_generated += len(bias_insights)
        
        return bias_insights
    
    def reflect_on_performance(self) -> Dict[str, Any]:
        """
        Refletir sobre desempenho geral.
        
        Returns:
            Análise de desempenho
        """
        analysis = {
            "overall_confidence": self.avg_confidence,
            "total_states_examined": self.total_states_examined,
            "patterns_detected": self.detect_cognitive_patterns(),
            "biases_detected": self.total_biases_detected,
            "insights_generated": self.total_insights_generated,
            "recommendations": []
        }
        
        # Gerar recomendações baseadas em análise
        if self.avg_confidence < 0.6:
            analysis["recommendations"].append("Increase confidence through validation")
        
        if self.total_biases_detected > 3:
            analysis["recommendations"].append("Address detected biases")
        
        patterns = analysis["patterns_detected"]
        if "High processing load pattern" in patterns:
            analysis["recommendations"].append("Optimize resource usage")
        
        return analysis
    
    def get_statistics(self) -> Dict:
        """Estatísticas do Introspection Engine"""
        return {
            "total_states_examined": self.total_states_examined,
            "total_insights_generated": self.total_insights_generated,
            "total_biases_detected": self.total_biases_detected,
            "avg_confidence": self.avg_confidence,
            "active_patterns": len(self.detect_cognitive_patterns()),
            "process_traces": len(self.process_traces)
        }


