# MÓDULO 43: ETHICAL REASONING ENGINE (POST 43)
# ═══════════════════════════════════════════════════════════════════════════

@dataclass
class EthicalDilemma:
    """Dilema ético"""
    dilemma_id: str
    description: str
    stakeholders: List[str]
    possible_actions: List[str]
    ethical_frameworks_applied: List[str]
    
@dataclass
class EthicalEvaluation:
    """Avaliação ética de uma ação"""
    evaluation_id: str
    action: str
    framework: str  # "utilitarian", "deontological", "virtue_ethics"
    score: float  # 0-1 (quão ética)
    reasoning: str
    consequences: List[str]
    
@dataclass
class EthicalConflict:
    """Conflito entre princípios éticos"""
    conflict_id: str
    principle1: str
    principle2: str
    severity: float  # 0-1
    resolution_strategy: str

class RealEthicalReasoningEngine:
    """
    POST43: Ethical Reasoning Engine — REAL Ethical and Moral Reasoning
    
    Raciocínio Ético = raciocínio sobre dilemas morais e decisões éticas.
    "Ethics is knowing the difference between what you have a right to do and what is right to do" - Potter Stewart
    
    Princípios Centrais:
    - Multi-framework analysis: Múltiplas perspectivas éticas
    - Stakeholder consideration: Considera todos os afetados
    - Consequence evaluation: Avalia consequências morais
    - Principle-based reasoning: Raciocínio baseado em princípios
    - Conflict resolution: Resolve conflitos éticos
    
    Componentes:
    1. Dilemma Analyzer: Analisa dilemas éticos
    2. Framework Applicator: Aplica frameworks éticos
    3. Consequence Evaluator: Avalia consequências morais
    4. Conflict Detector: Detecta conflitos éticos
    5. Resolution Engine: Propõe resoluções éticas
    
    Multiplica:
    • × POST7 (EthicsGuard): EthicsGuard + EthicalReasoning = ética completa
    • × POST8 (Executive): Executive usa raciocínio ético para decisões
    • × POST24 (Metacognition): Metacognition sobre raciocínio ético
    • × POST17 (Consciousness): Consciousness aplica ética
    
    Baseado em:
    - Utilitarian Ethics (Mill, 1863)
    - Deontological Ethics (Kant, 1785)
    - Virtue Ethics (Aristotle, 350 BCE)
    - Care Ethics (Gilligan, 1982)
    """
    
    def __init__(self, ethics_guard=None, executive=None, consciousness=None):
        self.ethics_guard = ethics_guard
        self.executive = executive
        self.consciousness = consciousness
        
        # Ethical dilemmas
        self.dilemmas: List[EthicalDilemma] = []
        
        # Evaluations
        self.evaluations: List[EthicalEvaluation] = []
        
        # Conflicts
        self.conflicts: List[EthicalConflict] = []
        
        # Ethical principles
        self.principles = [
            "autonomy",
            "beneficence",
            "non_maleficence",
            "justice",
            "honesty",
            "dignity"
        ]
        
        # Estatísticas
        self.total_dilemmas_analyzed = 0
        self.total_evaluations = 0
        self.total_conflicts_detected = 0
        self.avg_ethical_score = 0.0
        
        print("⚖️💭 POST 43 - RealEthicalReasoningEngine initialized (Ethical reasoning active)")
    
    def analyze_ethical_dilemma(self, description: str, 
                                stakeholders: List[str],
                                possible_actions: List[str]) -> EthicalDilemma:
        """
        Analisar dilema ético.
        
        Args:
            description: Descrição do dilema
            stakeholders: Partes interessadas
            possible_actions: Ações possíveis
        
        Returns:
            EthicalDilemma analisado
        """
        # Aplicar múltiplos frameworks éticos
        frameworks_applied = ["utilitarian", "deontological", "virtue_ethics"]
        
        dilemma = EthicalDilemma(
            dilemma_id=str(uuid.uuid4()),
            description=description,
            stakeholders=stakeholders,
            possible_actions=possible_actions,
            ethical_frameworks_applied=frameworks_applied
        )
        
        self.dilemmas.append(dilemma)
        self.total_dilemmas_analyzed += 1
        
        # Avaliar cada ação possível
        for action in possible_actions:
            for framework in frameworks_applied:
                self.evaluate_action(action, framework, stakeholders)
        
        return dilemma
    
    def evaluate_action(self, action: str, framework: str, 
                       stakeholders: List[str]) -> EthicalEvaluation:
        """
        Avaliar ação sob framework ético.
        
        Args:
            action: Ação a avaliar
            framework: Framework ético
            stakeholders: Partes interessadas
        
        Returns:
            EthicalEvaluation
        """
        # Avaliar baseado no framework
        if framework == "utilitarian":
            score, reasoning, consequences = self._evaluate_utilitarian(action, stakeholders)
        elif framework == "deontological":
            score, reasoning, consequences = self._evaluate_deontological(action)
        elif framework == "virtue_ethics":
            score, reasoning, consequences = self._evaluate_virtue_ethics(action)
        else:
            score, reasoning, consequences = 0.5, "Unknown framework", []
        
        evaluation = EthicalEvaluation(
            evaluation_id=str(uuid.uuid4()),
            action=action,
            framework=framework,
            score=score,
            reasoning=reasoning,
            consequences=consequences
        )
        
        self.evaluations.append(evaluation)
        self.total_evaluations += 1
        
        # Update statistics
        self._update_ethical_score(score)
        
        return evaluation
    
    def _evaluate_utilitarian(self, action: str, stakeholders: List[str]) -> tuple:
        """Avaliação utilitarista (maior bem para maior número)"""
        # Heurística: mais stakeholders beneficiados = melhor
        num_stakeholders = len(stakeholders)
        
        # Simular benefício
        if "help" in action.lower() or "benefit" in action.lower():
            score = 0.8
            reasoning = "Action maximizes overall welfare"
            consequences = [f"Benefits {num_stakeholders} stakeholders"]
        elif "harm" in action.lower() or "damage" in action.lower():
            score = 0.2
            reasoning = "Action reduces overall welfare"
            consequences = [f"Harms {num_stakeholders} stakeholders"]
        else:
            score = 0.5
            reasoning = "Action has neutral welfare impact"
            consequences = ["Neutral impact on stakeholders"]
        
        return score, reasoning, consequences
    
    def _evaluate_deontological(self, action: str) -> tuple:
        """Avaliação deontológica (baseada em deveres e regras)"""
        # Heurística: ações que violam princípios são imorais
        if "lie" in action.lower() or "deceive" in action.lower():
            score = 0.1
            reasoning = "Action violates duty of honesty"
            consequences = ["Breaks moral duty"]
        elif "respect" in action.lower() or "honor" in action.lower():
            score = 0.9
            reasoning = "Action upholds moral duty"
            consequences = ["Fulfills moral obligation"]
        else:
            score = 0.6
            reasoning = "Action is permissible under duty ethics"
            consequences = ["Complies with moral rules"]
        
        return score, reasoning, consequences
    
    def _evaluate_virtue_ethics(self, action: str) -> tuple:
        """Avaliação ética das virtudes (caráter e excelência)"""
        # Heurística: ações que demonstram virtudes são éticas
        virtues = ["courage", "honesty", "compassion", "wisdom"]
        
        action_lower = action.lower()
        virtue_count = sum(1 for v in virtues if v in action_lower)
        
        if virtue_count > 0:
            score = 0.7 + (virtue_count * 0.1)
            reasoning = f"Action demonstrates virtues: {virtue_count}"
            consequences = ["Develops virtuous character"]
        else:
            score = 0.5
            reasoning = "Action has neutral virtue implications"
            consequences = ["Neutral character development"]
        
        return score, reasoning, consequences
    
    def detect_ethical_conflicts(self, evaluations: List[EthicalEvaluation]) -> List[EthicalConflict]:
        """
        Detectar conflitos entre avaliações éticas.
        
        Args:
            evaluations: Avaliações para comparar
        
        Returns:
            Lista de conflitos detectados
        """
        conflicts = []
        
        # Comparar avaliações par a par
        for i, eval1 in enumerate(evaluations):
            for eval2 in evaluations[i+1:]:
                # Conflito se frameworks diferentes dão scores muito diferentes
                score_diff = abs(eval1.score - eval2.score)
                
                if score_diff > 0.4:  # Diferença significativa
                    conflict = EthicalConflict(
                        conflict_id=str(uuid.uuid4()),
                        principle1=eval1.framework,
                        principle2=eval2.framework,
                        severity=score_diff,
                        resolution_strategy=self._determine_resolution_strategy(eval1, eval2)
                    )
                    conflicts.append(conflict)
                    self.conflicts.append(conflict)
                    self.total_conflicts_detected += 1
        
        return conflicts
    
    def _determine_resolution_strategy(self, eval1: EthicalEvaluation, 
                                      eval2: EthicalEvaluation) -> str:
        """Determinar estratégia de resolução de conflito"""
        # Heurística: priorizar framework com score mais alto
        if eval1.score > eval2.score:
            return f"Prioritize {eval1.framework} approach"
        elif eval2.score > eval1.score:
            return f"Prioritize {eval2.framework} approach"
        else:
            return "Seek balanced compromise"
    
    def recommend_ethical_action(self, dilemma: EthicalDilemma) -> Dict[str, Any]:
        """
        Recomendar ação mais ética para dilema.
        
        Args:
            dilemma: Dilema ético
        
        Returns:
            Recomendação ética
        """
        # Obter avaliações para ações do dilema
        action_scores = {}
        
        for action in dilemma.possible_actions:
            # Calcular score médio entre frameworks
            action_evals = [e for e in self.evaluations 
                           if e.action == action]
            
            if action_evals:
                avg_score = sum(e.score for e in action_evals) / len(action_evals)
                action_scores[action] = avg_score
        
        # Recomendar ação com maior score
        if action_scores:
            best_action = max(action_scores.items(), key=lambda x: x[1])
            
            return {
                "recommended_action": best_action[0],
                "ethical_score": best_action[1],
                "reasoning": f"Highest average ethical score across frameworks",
                "all_scores": action_scores
            }
        
        return {
            "recommended_action": None,
            "ethical_score": 0.0,
            "reasoning": "No evaluations available",
            "all_scores": {}
        }
    
    def _update_ethical_score(self, score: float):
        """Atualizar estatísticas de score ético"""
        if self.avg_ethical_score == 0:
            self.avg_ethical_score = score
        else:
            self.avg_ethical_score = (self.avg_ethical_score + score) / 2
    
    def get_statistics(self) -> Dict:
        """Estatísticas do Ethical Reasoning Engine"""
        return {
            "total_dilemmas_analyzed": self.total_dilemmas_analyzed,
            "total_evaluations": self.total_evaluations,
            "total_conflicts_detected": self.total_conflicts_detected,
            "avg_ethical_score": self.avg_ethical_score,
            "active_dilemmas": len(self.dilemmas),
            "frameworks_used": ["utilitarian", "deontological", "virtue_ethics"]
        }


