# MÓDULO 46: UNCERTAINTY QUANTIFICATION ENGINE (POST 46)
# ═══════════════════════════════════════════════════════════════════════════

@dataclass
class UncertaintyEstimate:
    """Estimativa de incerteza"""
    estimate_id: str
    value: float  # Valor estimado
    uncertainty: float  # Incerteza (0-1)
    confidence_interval: Tuple[float, float]
    uncertainty_type: str  # "aleatoric", "epistemic", "total"
    
@dataclass
class ConfidenceAssessment:
    """Avaliação de confiança"""
    assessment_id: str
    prediction: Any
    confidence_score: float  # 0-1
    calibration_score: float  # 0-1 (quão bem calibrado)
    sources_of_uncertainty: List[str]
    
@dataclass
class UncertaintyDecomposition:
    """Decomposição de incerteza"""
    decomposition_id: str
    total_uncertainty: float
    aleatoric_uncertainty: float  # Incerteza irredutível (dados)
    epistemic_uncertainty: float  # Incerteza redutível (conhecimento)

class RealUncertaintyQuantificationEngine:
    """
    POST46: Uncertainty Quantification Engine — REAL Uncertainty Measurement
    
    Quantificação de Incerteza = medir e comunicar incerteza em previsões e decisões.
    "The only certainty is that nothing is certain" - Pliny the Elder
    
    Princípios Centrais:
    - Uncertainty estimation: Estimativa de incerteza
    - Confidence calibration: Calibração de confiança
    - Uncertainty decomposition: Separar tipos de incerteza
    - Risk quantification: Quantificar riscos
    - Probabilistic reasoning: Raciocínio probabilístico
    
    Componentes:
    1. Uncertainty Estimator: Estima incerteza em previsões
    2. Confidence Calibrator: Calibra confiança
    3. Uncertainty Decomposer: Separa incerteza aleatória vs epistêmica
    4. Risk Quantifier: Quantifica riscos
    5. Probabilistic Aggregator: Agrega incertezas
    
    Multiplica:
    • × POST24 (Metacognition): Metacognition sobre incerteza própria
    • × POST44 (Explainability): Explica fontes de incerteza
    • × POST2 (Reasoning): Reasoning probabilístico
    • × POST8 (Executive): Executive usa incerteza para decidir
    
    Baseado em:
    - Uncertainty Quantification (Sullivan, 2015)
    - Bayesian Deep Learning (Gal, 2016)
    - Calibration in ML (Guo et al., 2017)
    - Epistemic vs Aleatoric Uncertainty (Kendall & Gal, 2017)
    """
    
    def __init__(self, metacognition=None, explainability=None, reasoning=None):
        self.metacognition = metacognition
        self.explainability = explainability
        self.reasoning = reasoning
        
        # Uncertainty estimates
        self.estimates: List[UncertaintyEstimate] = []
        
        # Confidence assessments
        self.assessments: List[ConfidenceAssessment] = []
        
        # Uncertainty decompositions
        self.decompositions: List[UncertaintyDecomposition] = []
        
        # Estatísticas
        self.total_estimates = 0
        self.total_assessments = 0
        self.avg_uncertainty = 0.0
        self.avg_confidence = 0.0
        
        print("📊🎲 POST 46 - RealUncertaintyQuantificationEngine initialized (Uncertainty quantification active)")
    
    def estimate_uncertainty(self, value: float,
                            predictions: List[float],
                            uncertainty_type: str = "total") -> UncertaintyEstimate:
        """
        Estimar incerteza em uma previsão.
        
        Args:
            value: Valor central da previsão
            predictions: Múltiplas previsões (ensemble)
            uncertainty_type: Tipo de incerteza
        
        Returns:
            UncertaintyEstimate
        """
        # Calcular incerteza como desvio padrão das previsões
        if len(predictions) > 1:
            mean_pred = sum(predictions) / len(predictions)
            variance = sum((p - mean_pred) ** 2 for p in predictions) / len(predictions)
            uncertainty = variance ** 0.5
        else:
            uncertainty = 0.1  # Incerteza default mínima
        
        # Normalizar incerteza para 0-1
        uncertainty_normalized = min(1.0, uncertainty / (abs(value) + 1e-6))
        
        # Calcular intervalo de confiança (95%)
        margin = 1.96 * uncertainty  # Z-score para 95%
        confidence_interval = (value - margin, value + margin)
        
        estimate = UncertaintyEstimate(
            estimate_id=str(uuid.uuid4()),
            value=value,
            uncertainty=uncertainty_normalized,
            confidence_interval=confidence_interval,
            uncertainty_type=uncertainty_type
        )
        
        self.estimates.append(estimate)
        self.total_estimates += 1
        
        # Update statistics
        self._update_uncertainty_statistics(uncertainty_normalized)
        
        return estimate
    
    def assess_confidence(self, prediction: Any,
                         ground_truth: Optional[Any] = None,
                         prediction_probabilities: Optional[List[float]] = None) -> ConfidenceAssessment:
        """
        Avaliar confiança em uma previsão.
        
        Args:
            prediction: Previsão feita
            ground_truth: Verdade (se disponível)
            prediction_probabilities: Probabilidades das previsões
        
        Returns:
            ConfidenceAssessment
        """
        # Calcular confidence score
        if prediction_probabilities:
            confidence_score = max(prediction_probabilities)
        else:
            confidence_score = 0.5  # Confiança neutra
        
        # Calcular calibration score
        calibration_score = self._calculate_calibration(
            prediction, 
            ground_truth, 
            confidence_score
        )
        
        # Identificar fontes de incerteza
        sources = self._identify_uncertainty_sources(prediction_probabilities)
        
        assessment = ConfidenceAssessment(
            assessment_id=str(uuid.uuid4()),
            prediction=prediction,
            confidence_score=confidence_score,
            calibration_score=calibration_score,
            sources_of_uncertainty=sources
        )
        
        self.assessments.append(assessment)
        self.total_assessments += 1
        
        # Update statistics
        self._update_confidence_statistics(confidence_score)
        
        return assessment
    
    def _calculate_calibration(self, prediction: Any, 
                              ground_truth: Optional[Any],
                              confidence: float) -> float:
        """Calcular quão bem calibrado está a confiança"""
        if ground_truth is None:
            return 0.5  # Sem ground truth, calibração neutra
        
        # Heurística simples: se previsão correta, calibração = confidence
        # Se incorreta, calibração = 1 - confidence
        is_correct = (prediction == ground_truth)
        
        if is_correct:
            calibration = confidence
        else:
            calibration = 1.0 - confidence
        
        return calibration
    
    def _identify_uncertainty_sources(self, 
                                     probabilities: Optional[List[float]]) -> List[str]:
        """Identificar fontes de incerteza"""
        sources = []
        
        if probabilities:
            # Se probabilidades muito uniformes, alta incerteza epistêmica
            if probabilities:
                max_prob = max(probabilities)
                min_prob = min(probabilities)
                spread = max_prob - min_prob
                
                if spread < 0.3:
                    sources.append("High epistemic uncertainty (uniform probabilities)")
                
                # Se probabilidade máxima baixa, incerteza aleatória
                if max_prob < 0.6:
                    sources.append("High aleatoric uncertainty (low max probability)")
        else:
            sources.append("Unknown uncertainty sources")
        
        return sources
    
    def decompose_uncertainty(self, predictions: List[float],
                             model_predictions: List[List[float]]) -> UncertaintyDecomposition:
        """
        Decompor incerteza em aleatória vs epistêmica.
        
        Args:
            predictions: Previsões médias
            model_predictions: Previsões de múltiplos modelos
        
        Returns:
            UncertaintyDecomposition
        """
        # Incerteza total = variância de todas previsões
        all_preds = [p for model_preds in model_predictions for p in model_preds]
        total_var = self._calculate_variance(all_preds)
        
        # Incerteza epistêmica = variância entre modelos
        model_means = [sum(mp) / len(mp) for mp in model_predictions if mp]
        epistemic_var = self._calculate_variance(model_means) if model_means else 0.0
        
        # Incerteza aleatória = média da variância dentro dos modelos
        aleatoric_vars = [self._calculate_variance(mp) for mp in model_predictions]
        aleatoric_var = sum(aleatoric_vars) / len(aleatoric_vars) if aleatoric_vars else 0.0
        
        decomposition = UncertaintyDecomposition(
            decomposition_id=str(uuid.uuid4()),
            total_uncertainty=total_var ** 0.5,
            aleatoric_uncertainty=aleatoric_var ** 0.5,
            epistemic_uncertainty=epistemic_var ** 0.5
        )
        
        self.decompositions.append(decomposition)
        
        return decomposition
    
    def _calculate_variance(self, values: List[float]) -> float:
        """Calcular variância"""
        if not values or len(values) < 2:
            return 0.0
        
        mean = sum(values) / len(values)
        variance = sum((v - mean) ** 2 for v in values) / len(values)
        
        return variance
    
    def _update_uncertainty_statistics(self, uncertainty: float):
        """Atualizar estatísticas de incerteza"""
        if self.avg_uncertainty == 0:
            self.avg_uncertainty = uncertainty
        else:
            self.avg_uncertainty = (self.avg_uncertainty + uncertainty) / 2
    
    def _update_confidence_statistics(self, confidence: float):
        """Atualizar estatísticas de confiança"""
        if self.avg_confidence == 0:
            self.avg_confidence = confidence
        else:
            self.avg_confidence = (self.avg_confidence + confidence) / 2
    
    def quantify_risk(self, uncertainty: float, impact: float) -> Dict[str, Any]:
        """
        Quantificar risco baseado em incerteza e impacto.
        
        Args:
            uncertainty: Incerteza (0-1)
            impact: Impacto potencial (0-1)
        
        Returns:
            Quantificação de risco
        """
        # Risco = incerteza × impacto
        risk_score = uncertainty * impact
        
        # Classificar risco
        if risk_score < 0.3:
            risk_level = "low"
        elif risk_score < 0.6:
            risk_level = "medium"
        else:
            risk_level = "high"
        
        return {
            "risk_score": risk_score,
            "risk_level": risk_level,
            "uncertainty": uncertainty,
            "impact": impact,
            "recommendation": self._get_risk_recommendation(risk_level)
        }
    
    def _get_risk_recommendation(self, risk_level: str) -> str:
        """Obter recomendação baseada em nível de risco"""
        recommendations = {
            "low": "Proceed with standard protocols",
            "medium": "Gather more information before proceeding",
            "high": "Exercise extreme caution or seek expert review"
        }
        
        return recommendations.get(risk_level, "Unknown risk level")
    
    def get_statistics(self) -> Dict:
        """Estatísticas do Uncertainty Quantification Engine"""
        return {
            "total_estimates": self.total_estimates,
            "total_assessments": self.total_assessments,
            "avg_uncertainty": self.avg_uncertainty,
            "avg_confidence": self.avg_confidence,
            "active_estimates": len(self.estimates),
            "active_assessments": len(self.assessments)
        }


