# MÓDULO 51: SKILL COMPOSITION & DECOMPOSITION (POST 51)
# ═══════════════════════════════════════════════════════════════════════════

@dataclass
class AtomicSkill:
    """Habilidade atômica"""
    skill_id: str
    skill_name: str
    complexity: float  # 0-1
    mastery_level: float  # 0-1
    
@dataclass
class CompositeSkill:
    """Habilidade composta"""
    skill_id: str
    skill_name: str
    component_skills: List[str]  # IDs de sub-habilidades
    composition_quality: float  # 0-1
    
@dataclass
class SkillDecomposition:
    """Decomposição de habilidade"""
    decomposition_id: str
    original_skill: str
    atomic_components: List[AtomicSkill]
    decomposition_score: float  # 0-1

class RealSkillCompositionEngine:
    """
    POST51: Skill Composition & Decomposition — REAL Hierarchical Skill Building
    
    Skill Composition = compor habilidades complexas de habilidades simples hierarquicamente.
    "The whole is greater than the sum of its parts" - Aristotle
    
    Princípios Centrais:
    - Skill decomposition: Decompor habilidades complexas em atômicas
    - Hierarchical composition: Compor hierarquicamente
    - Transfer of components: Transferir componentes entre habilidades
    - Mastery tracking: Rastrear maestria em cada nível
    - Progressive building: Construir progressivamente
    
    Componentes:
    1. Skill Decomposer: Decompõe habilidades complexas
    2. Skill Composer: Compõe habilidades de componentes
    3. Mastery Tracker: Rastreia maestria
    4. Hierarchy Builder: Constrói hierarquias
    5. Transfer Facilitator: Facilita transferência de componentes
    
    Multiplica:
    • × POST48 (Transfer Learning): Transfer skills entre domínios
    • × POST9 (Incremental): Incremental skill building
    • × POST38 (Meta-Learning): Meta-learning sobre skill composition
    • × POST47 (Lifelong): Lifelong skill accumulation
    
    Baseado em:
    - Hierarchical Skills (Sutton et al., 1999)
    - Skill Chaining (Konidaris & Barto, 2009)
    - Compositional Learning (Lake et al., 2017)
    - Motor Skills Hierarchy (Bernstein, 1967)
    """
    
    def __init__(self, transfer=None, incremental=None, meta_learning=None):
        self.transfer = transfer
        self.incremental = incremental
        self.meta_learning = meta_learning
        
        # Atomic skills
        self.atomic_skills: List[AtomicSkill] = []
        
        # Composite skills
        self.composite_skills: List[CompositeSkill] = []
        
        # Decompositions
        self.decompositions: List[SkillDecomposition] = []
        
        # Estatísticas
        self.total_atomic_skills = 0
        self.total_composite_skills = 0
        self.total_decompositions = 0
        self.avg_composition_quality = 0.0
        
        print("🧩🏗️ POST 51 - RealSkillCompositionEngine initialized (Skill composition active)")
    
    def register_atomic_skill(self, skill_name: str,
                             complexity: float = 0.2,
                             mastery_level: float = 0.0) -> AtomicSkill:
        """
        Registrar habilidade atômica.
        
        Args:
            skill_name: Nome da habilidade
            complexity: Complexidade (0-1)
            mastery_level: Nível de maestria (0-1)
        
        Returns:
            AtomicSkill
        """
        skill = AtomicSkill(
            skill_id=str(uuid.uuid4()),
            skill_name=skill_name,
            complexity=complexity,
            mastery_level=mastery_level
        )
        
        self.atomic_skills.append(skill)
        self.total_atomic_skills += 1
        
        return skill
    
    def compose_skill(self, skill_name: str,
                     component_ids: List[str]) -> CompositeSkill:
        """
        Compor habilidade complexa de componentes.
        
        Args:
            skill_name: Nome da habilidade composta
            component_ids: IDs dos componentes
        
        Returns:
            CompositeSkill
        """
        # Verificar se componentes existem
        components = [s for s in self.atomic_skills if s.skill_id in component_ids]
        
        if len(components) != len(component_ids):
            # Algumas habilidades não encontradas
            missing = len(component_ids) - len(components)
            print(f"Warning: {missing} component skills not found")
        
        # Calcular qualidade de composição
        quality = self._calculate_composition_quality(components)
        
        composite = CompositeSkill(
            skill_id=str(uuid.uuid4()),
            skill_name=skill_name,
            component_skills=component_ids,
            composition_quality=quality
        )
        
        self.composite_skills.append(composite)
        self.total_composite_skills += 1
        
        # Update statistics
        self._update_composition_statistics(quality)
        
        return composite
    
    def _calculate_composition_quality(self, components: List[AtomicSkill]) -> float:
        """Calcular qualidade de composição"""
        if not components:
            return 0.0
        
        # Qualidade baseada em:
        # 1. Maestria média dos componentes
        # 2. Número de componentes (mais componentes = mais complexo)
        
        avg_mastery = sum(c.mastery_level for c in components) / len(components)
        component_diversity = min(1.0, len(components) / 5.0)
        
        quality = (avg_mastery + component_diversity) / 2.0
        
        return quality
    
    def decompose_skill(self, skill_name: str,
                       desired_complexity: float = 0.3) -> SkillDecomposition:
        """
        Decompor habilidade complexa em atômicas.
        
        Args:
            skill_name: Nome da habilidade a decompor
            desired_complexity: Complexidade desejada dos componentes
        
        Returns:
            SkillDecomposition
        """
        # Gerar componentes atômicos baseado no nome
        components = self._generate_atomic_components(skill_name, desired_complexity)
        
        # Calcular score de decomposição
        decomposition_score = self._calculate_decomposition_score(components)
        
        decomposition = SkillDecomposition(
            decomposition_id=str(uuid.uuid4()),
            original_skill=skill_name,
            atomic_components=components,
            decomposition_score=decomposition_score
        )
        
        # Adicionar componentes às atomic skills
        self.atomic_skills.extend(components)
        self.total_atomic_skills += len(components)
        
        self.decompositions.append(decomposition)
        self.total_decompositions += 1
        
        return decomposition
    
    def _generate_atomic_components(self, skill_name: str,
                                   complexity: float) -> List[AtomicSkill]:
        """Gerar componentes atômicos"""
        components = []
        
        # Heurística: dividir nome da habilidade em palavras-chave
        words = skill_name.lower().split()
        
        # Criar componente para cada palavra significativa
        for word in words:
            if len(word) > 3:  # Palavras significativas
                component = AtomicSkill(
                    skill_id=str(uuid.uuid4()),
                    skill_name=f"atomic_{word}",
                    complexity=complexity,
                    mastery_level=0.0
                )
                components.append(component)
        
        # Se nenhum componente gerado, criar um genérico
        if not components:
            component = AtomicSkill(
                skill_id=str(uuid.uuid4()),
                skill_name=f"atomic_{skill_name}",
                complexity=complexity,
                mastery_level=0.0
            )
            components.append(component)
        
        return components
    
    def _calculate_decomposition_score(self, components: List[AtomicSkill]) -> float:
        """Calcular score de decomposição"""
        if not components:
            return 0.0
        
        # Score baseado em número de componentes e complexidade
        num_components = min(1.0, len(components) / 3.0)
        avg_complexity = sum(c.complexity for c in components) / len(components)
        
        score = (num_components + (1.0 - avg_complexity)) / 2.0
        
        return score
    
    def get_skill_hierarchy(self, skill_id: str) -> Dict[str, Any]:
        """
        Obter hierarquia de habilidade.
        
        Args:
            skill_id: ID da habilidade
        
        Returns:
            Hierarquia da habilidade
        """
        # Procurar habilidade composta
        composite = next((s for s in self.composite_skills if s.skill_id == skill_id), None)
        
        if composite:
            # Construir hierarquia recursivamente
            hierarchy = {
                "skill_id": skill_id,
                "skill_name": composite.skill_name,
                "type": "composite",
                "quality": composite.composition_quality,
                "components": []
            }
            
            # Adicionar componentes
            for component_id in composite.component_skills:
                atomic = next((s for s in self.atomic_skills if s.skill_id == component_id), None)
                if atomic:
                    hierarchy["components"].append({
                        "skill_id": atomic.skill_id,
                        "skill_name": atomic.skill_name,
                        "type": "atomic",
                        "mastery": atomic.mastery_level
                    })
            
            return hierarchy
        
        # Se não é composta, verificar se é atômica
        atomic = next((s for s in self.atomic_skills if s.skill_id == skill_id), None)
        if atomic:
            return {
                "skill_id": skill_id,
                "skill_name": atomic.skill_name,
                "type": "atomic",
                "mastery": atomic.mastery_level
            }
        
        return {"error": "Skill not found"}
    
    def _update_composition_statistics(self, quality: float):
        """Atualizar estatísticas de composição"""
        if self.avg_composition_quality == 0:
            self.avg_composition_quality = quality
        else:
            self.avg_composition_quality = (self.avg_composition_quality + quality) / 2
    
    def get_statistics(self) -> Dict:
        """Estatísticas do Skill Composition Engine"""
        return {
            "total_atomic_skills": self.total_atomic_skills,
            "total_composite_skills": self.total_composite_skills,
            "total_decompositions": self.total_decompositions,
            "avg_composition_quality": self.avg_composition_quality,
            "active_atomic_skills": len(self.atomic_skills),
            "active_composite_skills": len(self.composite_skills)
        }


