# MÓDULO 53: MULTI-TASK COORDINATION SYSTEM (POST 53)
# ═══════════════════════════════════════════════════════════════════════════

@dataclass
class TaskDescriptor:
    """Descritor de tarefa"""
    task_id: str
    task_name: str
    priority: float  # 0-1
    deadline: Optional[float]
    resources_required: List[str]
    
@dataclass
class TaskSchedule:
    """Agendamento de tarefas"""
    schedule_id: str
    tasks: List[str]  # Task IDs
    execution_order: List[str]
    estimated_completion: float
    
@dataclass
class CoordinationResult:
    """Resultado de coordenação"""
    result_id: str
    tasks_coordinated: int
    parallel_tasks: int
    efficiency_score: float  # 0-1

class RealMultiTaskCoordinationSystem:
    """
    POST53: Multi-Task Coordination System — REAL Efficient Multi-Tasking
    
    Multi-Task Coordination = coordenar execução eficiente de múltiplas tarefas.
    "The key is not to prioritize what's on your schedule, but to schedule your priorities" - Stephen Covey
    
    Princípios Centrais:
    - Task scheduling: Agendamento inteligente de tarefas
    - Parallel execution: Execução paralela quando possível
    - Resource allocation: Alocação eficiente de recursos
    - Deadline management: Gerenciamento de deadlines
    - Priority-based coordination: Coordenação baseada em prioridades
    
    Componentes:
    1. Task Scheduler: Agenda tarefas otimizadamente
    2. Parallelization Detector: Detecta oportunidades de paralelização
    3. Resource Allocator: Aloca recursos eficientemente
    4. Deadline Tracker: Rastreia deadlines
    5. Coordination Optimizer: Otimiza coordenação
    
    Multiplica:
    • × POST8 (Executive): Executive coordena multi-tasking
    • × POST49 (Attention Routing): Attention routing para múltiplas tarefas
    • × POST28 (Budget): Budget enforcer para recursos multi-task
    • × POST45 (Collaborative): Collaborative intelligence para coordenação
    
    Baseado em:
    - Task Scheduling (Liu & Layland, 1973)
    - Multi-Tasking Psychology (Meyer & Kieras, 1997)
    - Parallel Processing (Amdahl, 1967)
    - Resource Allocation Theory (Wickens, 2002)
    """
    
    def __init__(self, executive=None, attention_routing=None, budget=None):
        self.executive = executive
        self.attention_routing = attention_routing
        self.budget = budget
        
        # Active tasks
        self.tasks: List[TaskDescriptor] = []
        
        # Schedules
        self.schedules: List[TaskSchedule] = []
        
        # Coordination results
        self.results: List[CoordinationResult] = []
        
        # Estatísticas
        self.total_tasks_coordinated = 0
        self.total_schedules = 0
        self.avg_efficiency = 0.0
        self.parallel_executions = 0
        
        print("📋⚡ POST 53 - RealMultiTaskCoordinationSystem initialized (Multi-task coordination active)")
    
    def add_task(self, task_name: str,
                priority: float = 0.5,
                deadline: Optional[float] = None,
                resources_required: Optional[List[str]] = None) -> TaskDescriptor:
        """
        Adicionar tarefa.
        
        Args:
            task_name: Nome da tarefa
            priority: Prioridade (0-1)
            deadline: Deadline (timestamp ou None)
            resources_required: Recursos necessários
        
        Returns:
            TaskDescriptor
        """
        task = TaskDescriptor(
            task_id=str(uuid.uuid4()),
            task_name=task_name,
            priority=priority,
            deadline=deadline,
            resources_required=resources_required or []
        )
        
        self.tasks.append(task)
        
        return task
    
    def schedule_tasks(self, task_ids: List[str]) -> TaskSchedule:
        """
        Agendar múltiplas tarefas.
        
        Args:
            task_ids: IDs das tarefas a agendar
        
        Returns:
            TaskSchedule
        """
        # Obter tarefas
        tasks = [t for t in self.tasks if t.task_id in task_ids]
        
        if not tasks:
            raise ValueError("No valid tasks found")
        
        # Ordenar por prioridade e deadline
        execution_order = self._determine_execution_order(tasks)
        
        # Estimar tempo de conclusão
        estimated_completion = self._estimate_completion_time(tasks)
        
        schedule = TaskSchedule(
            schedule_id=str(uuid.uuid4()),
            tasks=task_ids,
            execution_order=execution_order,
            estimated_completion=estimated_completion
        )
        
        self.schedules.append(schedule)
        self.total_schedules += 1
        
        return schedule
    
    def _determine_execution_order(self, tasks: List[TaskDescriptor]) -> List[str]:
        """Determinar ordem de execução"""
        # Ordenar por prioridade (maior primeiro)
        sorted_tasks = sorted(tasks, key=lambda t: t.priority, reverse=True)
        
        # Ajustar por deadline
        now = time.time()
        urgent_tasks = []
        normal_tasks = []
        
        for task in sorted_tasks:
            if task.deadline is not None and task.deadline - now < 3600:  # < 1 hora
                urgent_tasks.append(task)
            else:
                normal_tasks.append(task)
        
        # Urgentes primeiro
        ordered = urgent_tasks + normal_tasks
        
        return [t.task_id for t in ordered]
    
    def _estimate_completion_time(self, tasks: List[TaskDescriptor]) -> float:
        """Estimar tempo de conclusão"""
        # Heurística simples: 1 minuto por tarefa base
        base_time = len(tasks) * 60.0
        
        # Ajustar por prioridade (alta prioridade = mais tempo)
        priority_factor = sum(t.priority for t in tasks) / len(tasks)
        adjusted_time = base_time * (1.0 + priority_factor)
        
        return adjusted_time
    
    def coordinate_execution(self, schedule: TaskSchedule) -> CoordinationResult:
        """
        Coordenar execução de tarefas.
        
        Args:
            schedule: Agendamento de tarefas
        
        Returns:
            CoordinationResult
        """
        # Obter tarefas do schedule
        tasks = [t for t in self.tasks if t.task_id in schedule.tasks]
        
        # Detectar oportunidades de paralelização
        parallel_groups = self._detect_parallelizable_tasks(tasks)
        
        # Calcular eficiência
        efficiency = self._calculate_efficiency(tasks, parallel_groups)
        
        result = CoordinationResult(
            result_id=str(uuid.uuid4()),
            tasks_coordinated=len(tasks),
            parallel_tasks=sum(len(group) for group in parallel_groups),
            efficiency_score=efficiency
        )
        
        self.results.append(result)
        self.total_tasks_coordinated += len(tasks)
        
        if parallel_groups:
            self.parallel_executions += 1
        
        # Update statistics
        self._update_efficiency_statistics(efficiency)
        
        return result
    
    def _detect_parallelizable_tasks(self, 
                                    tasks: List[TaskDescriptor]) -> List[List[TaskDescriptor]]:
        """Detectar tarefas que podem executar em paralelo"""
        parallel_groups = []
        
        # Agrupar tarefas sem conflito de recursos
        used_resources = set()
        current_group = []
        
        for task in tasks:
            task_resources = set(task.resources_required)
            
            # Se não conflita com recursos já usados, adicionar ao grupo
            if not task_resources.intersection(used_resources):
                current_group.append(task)
                used_resources.update(task_resources)
            else:
                # Conflito: começar novo grupo
                if current_group:
                    if len(current_group) > 1:  # Só grupos com 2+ tarefas
                        parallel_groups.append(current_group)
                current_group = [task]
                used_resources = task_resources
        
        # Adicionar último grupo
        if current_group and len(current_group) > 1:
            parallel_groups.append(current_group)
        
        return parallel_groups
    
    def _calculate_efficiency(self, tasks: List[TaskDescriptor],
                            parallel_groups: List[List[TaskDescriptor]]) -> float:
        """Calcular eficiência de coordenação"""
        if not tasks:
            return 0.0
        
        # Eficiência baseada em:
        # 1. Taxa de paralelização
        # 2. Utilização de prioridades
        # 3. Respeito a deadlines
        
        parallelization_rate = sum(len(g) for g in parallel_groups) / len(tasks)
        avg_priority = sum(t.priority for t in tasks) / len(tasks)
        
        # Check deadline satisfaction
        now = time.time()
        deadline_satisfaction = 1.0
        for task in tasks:
            if task.deadline is not None and task.deadline < now:
                deadline_satisfaction *= 0.8  # Penalidade por deadline passado
        
        efficiency = (parallelization_rate + avg_priority + deadline_satisfaction) / 3.0
        
        return min(1.0, efficiency)
    
    def _update_efficiency_statistics(self, efficiency: float):
        """Atualizar estatísticas de eficiência"""
        if self.avg_efficiency == 0:
            self.avg_efficiency = efficiency
        else:
            self.avg_efficiency = (self.avg_efficiency + efficiency) / 2
    
    def get_statistics(self) -> Dict:
        """Estatísticas do Multi-Task Coordination System"""
        return {
            "total_tasks_coordinated": self.total_tasks_coordinated,
            "total_schedules": self.total_schedules,
            "parallel_executions": self.parallel_executions,
            "avg_efficiency": self.avg_efficiency,
            "active_tasks": len(self.tasks),
            "pending_schedules": len(self.schedules)
        }


